@namespace sv_38fa42a3bb7a4025988aafb68d9a5ac3.Components.Pages.Board

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge @PriorityClass">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="MoveLeftClicked">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="MoveRightClicked">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async Task MoveLeftClicked() => await OnMoveLeft.InvokeAsync();
    private async Task MoveRightClicked() => await OnMoveRight.InvokeAsync();
}

@namespace sv_38fa42a3bb7a4025988aafb68d9a5ac3.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn-add-task" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="title" />
        <input type="text" placeholder="Assignee" @bind="assignee" />
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="dueDate" />
        <div class="form-actions">
            <button class="btn-save" @onclick="Save">Save</button>
            <button class="btn-cancel" @onclick="Cancel">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<NewTaskModel> OnSave { get; set; }

    private bool IsVisible;
    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        IsVisible = false;
        ResetForm();
    }

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
        IsVisible = false;
        ResetForm();
    }

    private void ResetForm()
    {
        title = "";
        assignee = "";
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_38fa42a3bb7a4025988aafb68d9a5ac3.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, LeftStatus!))"
                      OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, RightStatus!))" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm OnSave="HandleNewTask" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public string Status { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public string? LeftStatus { get; set; }
    [Parameter] public string? RightStatus { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Status, AddTaskForm.NewTaskModel Model)> OnAddTask { get; set; }

    private bool ShowMoveLeft => LeftStatus is not null;
    private bool ShowMoveRight => RightStatus is not null;

    private async Task HandleNewTask(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync((Status, model));
    }
}

@page "/board"
@namespace sv_38fa42a3bb7a4025988aafb68d9a5ac3.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />

    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..." @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Status="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      LeftStatus="@null"
                      RightStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn Title="In Progress"
                      Status="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      LeftStatus="To Do"
                      RightStatus="Done"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn Title="Done"
                      Status="Done"
                      Tasks="GetFilteredTasks("Done")"
                      LeftStatus="In Progress"
                      RightStatus="@null"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Status, AddTaskForm.NewTaskModel Model) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(
                data.Model.Title, data.Model.Assignee, data.Model.Priority, data.Model.DueDate);
            tasks.Add(newTask);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

